-- Emit in-app notifications from persisted business events.
create or replace function public.drive_notify_admins() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.notifications(user_id,title,body,type) select p.id,'DRIVE activity','A new ride request was submitted.','ride_request' from public.profiles p where p.role='admin'::public.drive_role and p.is_active=true;return new;end $$;
create or replace function public.drive_notify_vehicle_owner() returns trigger language plpgsql security definer set search_path='' as $$ declare v_owner uuid;begin select owner_id into v_owner from public.vehicles where id=new.vehicle_id;if v_owner is not null then insert into public.notifications(user_id,title,body,type) values(v_owner,'New rental request','A customer submitted a rental request for your vehicle.','rental');end if;return new;end $$;
create or replace function public.drive_notify_renter() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.status is distinct from old.status then insert into public.notifications(user_id,title,body,type) values(new.renter_id,'Rental booking update','Your rental booking status is now '||new.status::text||'.','rental_status');end if;return new;end $$;
create or replace function public.drive_notify_ride_passenger() returns trigger language plpgsql security definer set search_path='' as $$ declare v_passenger uuid;begin if new.status is distinct from old.status then select passenger_id into v_passenger from public.ride_requests where id=new.request_id;if v_passenger is not null then insert into public.notifications(user_id,title,body,type) values(v_passenger,'Ride status update','Your ride status is now '||new.status::text||'.','ride_status');end if;end if;return new;end $$;
create or replace function public.drive_notify_sos_admins() returns trigger language plpgsql security definer set search_path='' as $$ begin if lower(new.alert_type)='sos' then insert into public.notifications(user_id,title,body,type) select p.id,'Emergency SOS alert',coalesce(new.message,'A passenger requested emergency assistance.'),'sos' from public.profiles p where p.role='admin'::public.drive_role and p.is_active=true;end if;return new;end $$;
create or replace function public.drive_notify_payment_user() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.status is distinct from old.status then insert into public.notifications(user_id,title,body,type) values(new.user_id,'Payment status update','Your payment status is now '||new.status||'.','payment');end if;return new;end $$;
drop trigger if exists drive_notify_admin_new_ride on public.ride_requests;create trigger drive_notify_admin_new_ride after insert on public.ride_requests for each row execute function public.drive_notify_admins();
drop trigger if exists drive_notify_owner_new_rental on public.rental_bookings;create trigger drive_notify_owner_new_rental after insert on public.rental_bookings for each row execute function public.drive_notify_vehicle_owner();
drop trigger if exists drive_notify_renter_status on public.rental_bookings;create trigger drive_notify_renter_status after update of status on public.rental_bookings for each row execute function public.drive_notify_renter();
drop trigger if exists drive_notify_passenger_status on public.rides;create trigger drive_notify_passenger_status after update of status on public.rides for each row execute function public.drive_notify_ride_passenger();
drop trigger if exists drive_notify_admin_sos on public.safety_alerts;create trigger drive_notify_admin_sos after insert on public.safety_alerts for each row execute function public.drive_notify_sos_admins();
drop trigger if exists drive_notify_payment_status on public.payments;create trigger drive_notify_payment_status after update of status on public.payments for each row execute function public.drive_notify_payment_user();
